/**
 * Build the single injectable engine bundle for the mobile WebView.
 *
 * react-native-webview injects one string of JavaScript into a loaded page
 * (via `injectedJavaScript`). This concatenates the SAME engine files the
 * extension ships — no forked copy — plus the overlay CSS (there is no
 * manifest to load a stylesheet on mobile, so we inject a <style> tag) and the
 * mobile entry point, into `mobile/dist/valyou-inject.js`.
 *
 * Dependency-free tooling, exactly like scripts/make-icons.js. Re-run whenever
 * the engine or the overlay changes:
 *
 *     node mobile/scripts/build-bundle.js
 *
 * The output is committed so the React Native app can `require` it as a string
 * without a bundler step.
 *
 * ── For a reader new to this codebase ──────────────────────────────────
 * There is no webpack/rollup here. "Bundling" just means reading several
 * source files as TEXT and concatenating them (with a bit of wrapper code)
 * into one big string, then writing that string out as a file. That's the
 * whole trick — everything below is string reading and joining.
 */
"use strict";

const fs = require("node:fs"); // read source files, write the bundle
const path = require("node:path"); // build OS-independent paths

// Repo root: this file is at <repo>/mobile/scripts, so ".." twice climbs out.
const REPO = path.join(__dirname, "..", "..");

/**
 * Engine files, in dependency order — the same modules the extension loads,
 * minus the ones that need chrome.* (crypto/store/settings/service worker):
 * those live natively on mobile. mobile-main replaces content/main.js.
 */
// Order matters: a file that uses another must come AFTER it, since they are
// simply pasted together and run top-to-bottom in one scope.
const JS_FILES = [
  "src/lib/text.js",
  "src/lib/taxonomy.js",
  "src/lib/lexicon.js",
  "src/lib/ml.js",
  "src/model/model-data.js",
  "src/lib/scorer.js",
  "src/content/extractors.js",
  "src/content/apply.js",
  "mobile/inject/mobile-main.js",
];

const CSS_FILE = "src/content/overlay.css";
const OUT_FILE = path.join(REPO, "mobile", "dist", "valyou-inject.js");

/**
 * Wrap the overlay CSS in an injector that adds a <style> tag once.
 *
 * @param {string} css Stylesheet text.
 * @returns {string} JavaScript that installs it.
 */
function cssInjector(css) {
  // JSON.stringify turns the CSS text into a safely-quoted, escaped JS string
  // literal we can paste into the generated code. We build the injector as an
  // array of source LINES and .join("\n") them into one string. The generated
  // code creates a <style> element, fills it with the CSS, and appends it —
  // guarded so it only ever runs once (checks for an existing element by id).
  const literal = JSON.stringify(css);
  return [
    "(function(){",
    "  if (document.getElementById('valyou-overlay-css')) return;",
    "  var s = document.createElement('style');",
    "  s.id = 'valyou-overlay-css';",
    "  s.textContent = " + literal + ";",
    "  (document.head || document.documentElement).appendChild(s);",
    "})();",
  ].join("\n");
}

function main() {
  // `parts` collects every piece of the bundle in order; we join it at the end.
  // It opens with a banner, then an IIFE wrapper whose first line makes the
  // whole thing idempotent — if this bundle was already injected into the page,
  // the flag is set and it returns early instead of running twice.
  const parts = [
    "/* valyou mobile inject bundle — generated by mobile/scripts/build-bundle.js. Do not edit. */",
    "(function(){",
    "if (window.__VALYOU_INJECTED__) return; window.__VALYOU_INJECTED__ = true;",
  ];

  // Overlay styles first, so filtered content is styled the instant it is hidden.
  // readFileSync(..., "utf8") returns the file's contents as a string.
  parts.push(cssInjector(fs.readFileSync(path.join(REPO, CSS_FILE), "utf8")));

  // Then the engine, each file as-is (they self-register on window.VALYOU).
  for (const rel of JS_FILES) {
    const code = fs.readFileSync(path.join(REPO, rel), "utf8"); // the file's source text
    parts.push("/* ===== " + rel + " ===== */"); // a marker comment for readability/debugging
    parts.push(code);
  }

  parts.push("})();"); // close the wrapper IIFE
  // react-native-webview requires the injected string to end with `true;` so
  // the WebView does not warn about a non-serialisable return value.
  parts.push("true;");

  // Glue all the pieces into the final bundle text with newlines between them.
  const bundle = parts.join("\n");
  fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true }); // ensure dist/ exists (dirname = the folder)
  fs.writeFileSync(OUT_FILE, bundle);

  // Metro (React Native) can't import a raw .js as a *string* without a custom
  // transformer — a normal require would execute it. So also emit a plain JS
  // module that exports the bundle as a string literal. The app requires this
  // one; the Node test suite reads the .js above and runs it in a vm sandbox.
  // Both come from the identical `bundle`, so there is no drift between what is
  // tested and what ships.
  const MODULE_FILE = path.join(path.dirname(OUT_FILE), "valyou-inject.bundle.js");
  // Emit a tiny CommonJS module whose export IS the bundle text. JSON.stringify
  // turns the whole bundle into one big quoted/escaped string literal, so
  // `require`-ing this file hands back the code as a STRING (to inject) rather
  // than executing it.
  fs.writeFileSync(
    MODULE_FILE,
    "/* generated by mobile/scripts/build-bundle.js — do not edit */\n" +
      "module.exports = " +
      JSON.stringify(bundle) +
      ";\n"
  );

  // Buffer.byteLength = size in bytes (not characters); report both outputs.
  const kb = (Buffer.byteLength(bundle) / 1024).toFixed(0);
  process.stdout.write("wrote " + OUT_FILE + " (" + kb + " KB)\n");
  process.stdout.write("wrote " + MODULE_FILE + " (string module)\n");
}

// Expose the file list/helpers so the test suite can import them.
module.exports = { JS_FILES, CSS_FILE, cssInjector };

// Only auto-run when invoked directly (`node build-bundle.js`), not when required.
if (require.main === module) main();
